insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-17','opgelost','Dossiers','Categorie wijzigen verplaatst het dossier meteen',
   'Zet je een dossier op Dagelijks onderhoud of Mutatie, dan staat het direct op de Servicedesk — en meteen in de juiste kolom, passend bij de fase waarin het werk staat. Tot nu toe bleef het tot de volgende Bouw7-synchronisatie tussen de opdrachten staan.');
